(function(root){
'use strict';
const types=['Visuales','Artes finales','Propuestas'];
const id=()=>globalThis.crypto.randomUUID();
function seed(now=Date.now()){return {version:1,revision:0,userId:'demo-user',users:[{id:'demo-user',name:'Perfil demo'}],projects:[{id:'demo-p1',name:'Campaña de primavera',client:'Estudio Demo',historicalMinutes:120,archived:false},{id:'demo-p2',name:'Packaging colección',client:'Cliente Ejemplo',historicalMinutes:60,archived:false}],sessions:[{id:'sample',projectId:'demo-p1',userId:'demo-user',description:'Exploración visual',workType:'Visuales',units:2,start:now-7200000,end:now-5400000}],active:null};}
function validate(s,state,now=Date.now()){if(!state.projects.some(p=>p.id===s.projectId))throw Error('Selecciona un proyecto válido.');if(!state.users.some(u=>u.id===s.userId))throw Error('Perfil desconocido.');if(!Number.isFinite(s.start)||!Number.isFinite(s.end)||s.end<=s.start)throw Error('El fin debe ser posterior al inicio.');if(s.end>now+1000)throw Error('No puedes registrar tiempo futuro.');if(!Number.isInteger(s.units)||s.units<0||s.units>100000)throw Error('Las unidades deben ser un entero entre 0 y 100000.');if(!types.includes(s.workType))throw Error('Tipo de trabajo inválido.');if(typeof s.description!=='string'||s.description.length>500)throw Error('Máximo 500 caracteres.');if(state.sessions.some(x=>x.id!==s.id&&x.userId===s.userId&&s.start<x.end&&s.end>x.start))throw Error('La sesión se solapa con otra del mismo perfil.');if(state.active&&state.active.id!==s.id&&state.active.userId===s.userId&&s.end>state.active.start)throw Error('La sesión se solapa con el temporizador activo.');return s;}
function start(state,draft,now=Date.now()){if(state.active)throw Error('Ya hay un temporizador en marcha.');const p=state.projects.find(p=>p.id===draft.projectId);if(!p||p.archived)throw Error('Selecciona un proyecto activo.');if(!Number.isInteger(draft.units)||draft.units<0||draft.units>100000)throw Error('Revisa las unidades.');state.active={...draft,id:id(),userId:state.userId,start:now};return state.active;}
function own(state,s){if(!state.users.some(u=>u.id===state.userId)||!s||s.userId!==state.userId)throw Error('Esta sesión no pertenece al perfil activo.');return s;}
function mine(state){return state.users.some(u=>u.id===state.userId)?state.sessions.filter(s=>s.userId===state.userId):[];}
function stop(state,now=Date.now()){if(!state.active)return null;own(state,state.active);const s={...state.active,end:Math.max(now,state.active.start+1)};validate(s,state,now);state.sessions.unshift(s);state.active=null;return s;}
function upsert(state,s,now=Date.now()){own(state,s);const existing=state.sessions.find(x=>x.id===s.id);if(existing)own(state,existing);validate(s,state,now);const i=state.sessions.findIndex(x=>x.id===s.id);if(i<0)state.sessions.unshift(s);else state.sessions[i]=s;}
function remove(state,id){own(state,state.sessions.find(s=>s.id===id));state.sessions=state.sessions.filter(s=>s.id!==id);}
function daily(state,start,end){return mine(state).filter(s=>dayOverlap(s,start,end)>0).sort((a,b)=>a.start-b.start);}
function personalBackup(state){return {...state,users:state.users.filter(u=>u.id===state.userId),sessions:mine(state),active:state.active?.userId===state.userId?state.active:null};}
function dayOverlap(s,start,end){return Math.max(0,Math.min(s.end,end)-Math.max(s.start,start));}
function seconds(s){return Math.max(0,Math.floor((s.end-s.start)/1000));}
function format(s){s=Math.max(0,Math.floor(s));return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(v=>String(v).padStart(2,'0')).join(':');}
function csv(rows){const safe=v=>{let t=String(v??'');if(/^[=+@\-\t\r]/.test(t))t="'"+t;return '"'+t.replaceAll('"','""')+'"';};return '\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n');}
const api={seed,validate,start,stop,upsert,remove,own,mine,daily,personalBackup,dayOverlap,seconds,format,csv,id,types};if(typeof module!=='undefined')module.exports=api;else root.Tracker=api;
})(globalThis);
